import React, { createContext, useContext } from 'react';
import { useSession } from './session';
import type { SessionAdapter } from './session';
import { routeData } from './route-data';
import { fetchSession, signInRequest, signOutRequest } from '../api/auth';
import type { AuthUser } from '../api/auth';

export type Credentials = { identifier: string; password: string };
export type AppSession = ReturnType<typeof useSession<AuthUser | null, Credentials>>;

// Stable module-level adapter: the same read/signIn/signOut identities for every
// render, so the shared session hook does not restart on each render.
const sessionAdapter: SessionAdapter<AuthUser | null, Credentials> = {
  read: async (signal) => {
    // The server already authorized the shared session snapshot for this
    // document; reuse it before making another request.
    const snapshot = routeData.read<AuthUser | null>('session');
    if (snapshot.hasData) return snapshot.data ?? null;
    return fetchSession(signal);
  },
  signIn: (credentials) => signInRequest(credentials.identifier, credentials.password),
  signOut: () => signOutRequest(),
};

const SessionContext = createContext<AppSession | null>(null);

export function SessionProvider({ children }: { children: React.ReactNode }) {
  const session = useSession<AuthUser | null, Credentials>(sessionAdapter);
  return <SessionContext.Provider value={session}>{children}</SessionContext.Provider>;
}

export function useAppSession(): AppSession {
  const value = useContext(SessionContext);
  if (!value) throw new Error('useAppSession must be used inside a SessionProvider');
  return value;
}
import { useCallback, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { AsyncContent, Disclosure, PageSection, copyText, usePageResource } from '../ui';
import { RouteAction } from '../competition';
import { readRepository } from '../api/repos';
import { blobUrl as repoBlobUrl, commitsUrl, treeUrl } from '../components/repo-code';
import AddFileMenu from '../components/AddFileMenu';
import RepositorySearchBox from '../components/RepositorySearchBox';
import type { RepositoryDetail } from '../api/repos';

function CloneMenu({ owner, repo }: { owner: string; repo: string }) {
  const [tab, setTab] = useState<'https' | 'ssh'>('https');
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const value = tab === 'https'
    ? `https://github.com/${owner}/${repo}.git`
    : `git@github.com:${owner}/${repo}.git`;

  const copy = () => {
    setError(null);
    void copyText(value).then(() => {
      setCopied(true);
      window.setTimeout(() => setCopied(false), 5000);
    }).catch(() => setError('Copy failed'));
  };

  return <Disclosure label="Code">
    <div role="tablist" aria-label="Clone">
      <button type="button" role="tab" aria-selected={tab === 'https'}
        onClick={() => { setTab('https'); setCopied(false); }}>HTTPS</button>
      <button type="button" role="tab" aria-selected={tab === 'ssh'}
        onClick={() => { setTab('ssh'); setCopied(false); }}>SSH</button>
    </div>
    <div role="tabpanel">
      <code>{value}</code>
      <button type="button" onClick={copy}>Copy</button>
    </div>
    {copied && <span role="status">Copied</span>}
    {error && <span role="alert">{error}</span>}
  </Disclosure>;
}

export default function RepositoryOverviewPage() {
  const { owner = '', repo = '' } = useParams();
  const read = useCallback(() => readRepository(owner, repo), [owner, repo]);
  const snapshot = usePageResource<RepositoryDetail>(`repository:${owner}:${repo}`, read);
  const detail = snapshot.data;
  const repository = detail?.repository;
  const branch = detail?.defaultBranch ?? repository?.defaultBranch ?? 'main';

  const title = repository ? `${repository.owner}/${repository.name}` : `${owner}/${repo}`;
  const commits = detail?.commits ?? [];

  return <PageSection title={title}>
    <AsyncContent pending={snapshot.status === 'pending'} error={snapshot.status === 'error'}
      hasData={snapshot.hasData} pendingContent="Loading repository…"
      errorContent="Repository could not be loaded.">
      {detail && detail.denied && <p role="alert">Access denied</p>}
      {repository && <>
        {repository.ownerType === 'organization' && repository.owner
          ? <p><Link to={`/organizations/${repository.owner}`}>{repository.ownerDisplayName}</Link></p>
          : <p>{repository.ownerDisplayName}</p>}
        <p>{repository.description}</p>
        <p>{repository.visibility === 'private' ? 'Private' : 'Public'}</p>
        {repository.forkedFrom && <p>
          {'Forked from '}
          <Link to={`/repos/${repository.forkedFrom.owner}/${repository.forkedFrom.name}`}>
            {repository.forkedFrom.name}
          </Link>
        </p>}
        <p>{`Default branch: ${branch}`}</p>
        <nav aria-label="Repository">
          <ul>
            <li><Link to={treeUrl(owner, repo, branch)}>Code</Link></li>
            <li><Link to={commitsUrl(owner, repo, branch)}>Commits</Link></li>
            <li><Link to={`/repos/${owner}/${repo}/issues`}>Issues</Link></li>
            <li><Link to={`/repos/${owner}/${repo}/pulls`}>Pull requests</Link></li>
            {detail.canAdmin && <li><Link to={`/repos/${owner}/${repo}/settings`}>Settings</Link></li>}
          </ul>
        </nav>
        <CloneMenu owner={repository.owner ?? owner} repo={repository.name} />
        <RepositorySearchBox owner={owner} repo={repo} branch={branch} />
        <div>
          <RouteAction to={`/repos/${owner}/${repo}/fork`}>Fork</RouteAction>
          {detail.canWrite && <AddFileMenu owner={owner} repo={repo} branch={branch} />}
        </div>
        <section aria-label="Files">
          <h2>Files</h2>
          <ul>
            {(detail.entries && detail.entries.length > 0
              ? detail.entries
              : (detail.files ?? []).map((file) => ({ ...file, type: 'file' as const })))
              .map((entry) => <li key={entry.path}>
                <Link to={entry.type === 'dir'
                  ? treeUrl(owner, repo, branch, entry.path)
                  : repoBlobUrl(owner, repo, branch, entry.path)}>{entry.name}</Link>
              </li>)}
          </ul>
        </section>
        <section aria-label="Commits">
          <h2>{commits.length === 1 ? '1 commit' : `${commits.length} commits`}</h2>
          <ul>
            {commits.map((commit) => <li key={commit.id}>
              <span>{commit.message}</span>
            </li>)}
          </ul>
        </section>
      </>}
    </AsyncContent>
  </PageSection>;
}
