                    filters=[_identifier(column)+' = ? COLLATE NOCASE']
                    values=[fact['name']]
                    for k,v in where.items():
                        filters.append(_identifier(k)+(' IS NULL' if v is None else ' = ?'))
                        if v is not None:values.append(v)
                    exists=db.execute('SELECT 1 FROM '+_identifier(table)+' WHERE '+' AND '.join(filters)+' LIMIT 1',values).fetchone() is not None
                    valid_subjects[fact['id']] = (binding, filters, values)
                    report['checked'].append({'fact_id':fact['id'],'table':table,'column':column,'where':where,'exists':exists})
                target=('present' if exists else 'missing') if fact['predicate']=='exists' else ('unexpected' if exists else 'absent')
                report[target].append(fact)
            for constraint in compiled.get('constraints', []):
                subject = valid_subjects.get(constraint['subject_id'])
                if subject is None:
                    report['unverified'].append({**constraint, 'reason':'constraint_subject_not_bound'})
                    continue
                binding, filters, values = subject
                table = binding['table']
                mapping = binding.get('fields', {})
                if not isinstance(mapping, dict):
                    raise ValueError('Schema fields mapping must be an object')
                columns = [mapping.get(field) for field in constraint['fields']]
                if any(not isinstance(c, str) or c not in schema[table] for c in columns):
                    report['unverified'].append({**constraint, 'reason':'constraint_fields_not_bound'})
                    continue
                # Source defines ANY and the literal. Model can only bind physical columns.
                predicate = ' OR '.join('instr(CAST('+_identifier(c)+' AS TEXT), ?) > 0' for c in columns)
                exists = db.execute('SELECT 1 FROM '+_identifier(table)+' WHERE '+' AND '.join(filters)+
                    ' AND ('+predicate+') LIMIT 1', [*values, *[constraint['value'] for _ in columns]]).fetchone() is not None
                report['constraints_checked'].append({'constraint_id':constraint['id'], 'passed':exists})
                if not exists:
                    report['violations'].append(constraint)
            if report['binding_errors']:
                report['error'] = 'Invalid initial-state mapping: '+json.dumps(report['binding_errors'],ensure_ascii=False)
    except (sqlite3.Error,ValueError,TypeError,TimeoutError) as exc:
        report['error']=str(exc)
    if report['unverified']:report['coverage_status']='partial'
    return report
